def validate_proposed_band(spec,label):
 if label is not None and label not in [x['label'] for x in spec['bands']]:raise ValueError('UNSUPPORTED_M3_BAND')

def build(ledger):
 financial=ledger['financials'];byid={x['id']:x for x in financial.values()};specs=n.p1.module('p26_specs','scripts/build-dfr02.py').rubrics();out=[]
 def ids(keys):return [x['id'] for x in financial.values() if x['key'] in keys and x.get('year')==2025 and x['value'] is not None]
 for spec in specs:
  rid=spec['id'];support,counter,text,missing,assumptions=ROWS[rid]
  qualified=rid=='FH-BS';topic={}
  validate_proposed_band(spec,'Adequate' if qualified else None)
  if qualified:
   topic={'capital':ids(['REPORTED_CAR','TIER1_RATIO','REG_CAPITAL_RECONCILIATION','REPORTED_FLOOR_CAR_BUFFER']),'asset_quality':ids(['NPL_BANK_CORE_RATIO','NPL_COVERAGE_BANK_CORE','GROUP2_BANK_CORE_RATIO','REAL_ESTATE_BUSINESS_SHARE']),'funding':ids(['CUSTOMER_DEPOSITS','DEMAND_DEPOSIT_SHARE','FI_DEPOSITS','FI_BORROWINGS','ISSUED_INSTRUMENTS','LIQ_GAP_LT1M']),'leverage_context':ids(['GROUP_EQUITY','PARENT_EQUITY','GROUP_GROSS_LOANS','TOTAL_RWA'])}
  out.append(dict(ticker='TCB',rubric=rid,category=spec['category'],classification='DRAFT_RESEARCH_ASSESSMENT',requiredTopics=spec['topics'],status='QUALIFIED_HISTORICAL_DRAFT' if qualified else 'BLOCKED_FOR_COMPLETE_ASSESSMENT',allMandatoryTopicsQualified=qualified,qualificationScope='Reported FY2025 balance-sheet assessment only; no current/as-known/valuation/decision acceptance' if qualified else None,businessAssessment=text,supportingEvidence=ids(support),contradictoryEvidence=ids(counter),reportedDisclosureEvidence=[x['id'] for x in ledger['narratives'] if (rid=='RG-GOV' and any(k in x['id'] for k in ['AUDIT','SHARE','RELATED','RISK_GOVERNANCE'])) or (rid.startswith('CA-') and 'ALLOCATION' in x['id']) or (rid=='FH-LIQ' and 'MATURITY' in x['id']) or (rid=='BQ-MOAT' and 'BUSINESS_MODEL' in x['id'])],topicQualification=topic,analystReasoning=text+' Counterevidence limits the inference; no ratio automatically chooses a band.',confidence='MEDIUM_FOR_HISTORICAL_RESEARCH' if qualified else 'LOW_FOR_FULL_TOPIC; reported-fact transcription separately HIGH',riskFactors=[ISSUE_RISK[rid]],assumptionDependencies=assumptions,proposedQualitativeBand='Adequate' if qualified else None,maximumPrerequisitesMet=False,maximumBandRejected='Strong — normalized/downside resilience not demonstrated' if qualified else None,missingEvidence=[] if qualified else [missing],conditions=[missing] if qualified else [],invalidationConditions=['A material qualified source revision or population error changes the disclosed capital/asset-quality/funding evidence; a newly approved case cutoff introduces materially different data.'] if qualified else ['Do not promote until every named missing topic, source authority and applicable assumption is qualified.'],points=None,band=None,assessment=None,totalScore=None,productionAdmissible=False,scoringAuthorized=False))
 return out

ISSUE_RISK={
'BQ-EQ':'Parent attribution, other-equity classification and normalized losses can materially alter common returns.',
'BQ-MOAT':'Demand funding may not be sticky or competitively cheaper after full expense allocation.',
'BQ-CASH':'Accrued/uncollected interest and acquisition/fee timing may overstate sustainable realization.',
'BQ-RES':'Property borrowers, deposit behavior and margin lending may correlate in a market shock.',
'FH-BS':'Reported regulatory buffers may erode under correlated property losses, margin stress and funding shocks; no survival certificate.',
'FH-LIQ':'Behavioural maturity and required reserves overstate immediately usable liquidity if misread as contractual/free cash.',
'FH-STRESS':'Uncalibrated losses/outflows cannot establish capital/funding survival.',
'GQ-HIST':'Group, parent, common-EPS and action-adjusted growth are distinct; acquisitions/minority capital create base effects.',
'GQ-FWD':'Past credit expansion may exhaust capital or worsen underwriting; no forecast from history.',
'GQ-INC':'NCI and capital actions contaminate naive incremental-equity denominators.',
'IC-IND':'Issuer self-description cannot establish industry rationality or durable returns.',
'IC-POS':'No peer-compatible denominator or independently qualified leadership evidence.',
'IC-CYCLE':'Current NPL/credit charges may be cyclically unrepresentative.',
'VAL-PRIMARY':'Common capital/normalization and cost of equity uncertainty dominate a book-multiple formula.',
'VAL-RET':'Unqualified price, actions, payout and terminal assumptions can fabricate return.',
'VAL-MOS':'An unqualified intrinsic range cannot create a margin of safety.',
'RG-GOV':'Disclosure alone does not establish transaction fairness or minority protection.',
'RG-RISK':'Repeatedly penalizing one property/NPL channel would double count; mitigation effectiveness unknown.',
'RG-UNC':'Exact transcription is not forecast precision.',
'CA-REINV':'New insurance/control and capital events have limited subsequent economic outcome evidence.',
'CA-DIST':'A paid/declared dividend does not prove disciplined allocation or sustainable payout capacity.',
'CA-DIL':'Share growth and equal basic/diluted denominator do not prove issue terms are fair.',
'CA-PSV':'A two-point accounting EPS increase can conceal cycle, actions and value changes.'}
